const app = document.querySelector('#app');
const storedFleetVehicles=(()=>{try{const value=JSON.parse(localStorage.getItem('fleetVehicles')||'[]');return Array.isArray(value)?value:[]}catch{return []}})();
const state = {summary: [], routes: [], ffSummary: [], ffRoutes: [], spotSummary: [], spotRoutes: [], snapshotFFRoutes: [], snapshotSpotRoutes: [], snapshotFFSummary: [], ddsRoutes: [], ffLogicRows: [], ffLogicSummary: [], mercadoRows: [], ddsRows: [], fleetReference: {master: []}, fleetByPlate: new Map(), plateRankings: {ff: [], spot: []}, fleetVehicles: storedFleetVehicles, reserve: [], rawImportRows: [], mode: 'ff', view: 'dashboard', query: '', routePage: 1, baseSort: 'ranking'};
let latestImportsSignature = '';
let modeSwitchFrame = 0;
let spotMetricsCache = {routes: null, metrics: null};
const money = n => n.toLocaleString('pt-BR', {style:'currency', currency:'BRL', maximumFractionDigits:0});
const pct = n => n===null||n===undefined||n===''||!Number.isFinite(Number(n))?'—':`${(Number(n)*100).toFixed(1).replace('.', ',')}%`;
const pctWhole = n => n===null||n===undefined||n===''||!Number.isFinite(Number(n))?'—':`${Number(n).toFixed(1).replace('.', ',')}%`;
const esc = v => String(v ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const project = v => v && String(v).trim() ? v : 'Não informado';
function driverLabel(row,limit=2){const names=Array.isArray(row?.driver_names)?row.driver_names.filter(Boolean):row?.driver_name?[row.driver_name]:[];return names.length?names.slice(0,limit).join(' · ')+(names.length>limit?` +${names.length-limit}`:''):'—'}
function bonusBandLabel(row){if(state.mode==='spot'){const band=spotBandForCars(Number(row?.spot_cars||0));return band?`${band.cars} carros`:'Nenhuma'}const share=Number(row?.ff_share);if(!Number.isFinite(share))return 'Nenhuma';return share>=1?'100%':share>=.95?'95%':share>=.9?'90%':'Nenhuma'}
function baseSortRows(rows){const spot=state.mode==='spot',bonuses=spot?spotMonthlyBonusMap():{};return rows.map(row=>{const detail=bonuses[row.base];return detail?{...row,spot_cars:detail.cars,spot_bonus:detail.bonus,spot_eligible_routes:detail.eligibleRoutes}:row}).sort((a,b)=>{const sort=state.baseSort||'ranking';if(sort==='name')return String(a.base).localeCompare(String(b.base),'pt-BR');if(sort==='worst'){const ads=Number(a.ff_ds),bds=Number(b.ff_ds);return (Number.isFinite(ads)?ads:Infinity)-(Number.isFinite(bds)?bds:Infinity)}if(spot){const av=sort==='ds'?Number(a.ff_ds):sort==='share'?Number(a.spot_cars||0):Number(a.spot_bonus||0),bv=sort==='ds'?Number(b.ff_ds):sort==='share'?Number(b.spot_cars||0):Number(b.spot_bonus||0);return bv-av||Number(b.ff_ds||0)-Number(a.ff_ds||0)}const av=sort==='ds'?Number(a.ff_ds):sort==='share'?Number(a.ff_share):payoutProxy(a),bv=sort==='ds'?Number(b.ff_ds):sort==='share'?Number(b.ff_share):payoutProxy(b);return (Number.isFinite(bv)?bv:-Infinity)-(Number.isFinite(av)?av:-Infinity)||Number(b.ff_ds||0)-Number(a.ff_ds||0)})}
function baseToolbar(){const options=[['ranking','Ranking · melhor → pior'],['bonus','Bônus maior → menor'],['ds','DS médio maior → menor'],['share',state.mode==='spot'?'Média diária maior → menor':'Participação/utilização maior → menor'],['worst','Pior desempenho'],['name','Base A → Z']];return `<div class="filterbar base-filterbar"><input class="search-input" id="viewSearch" placeholder="Buscar por Base" value="${esc(state.query)}" /><label class="sort-control"><span>Ordenar</span><select id="baseSortSelect" class="filter-select">${options.map(([value,label])=>`<option value="${value}" ${state.baseSort===value?'selected':''}>${label}</option>`).join('')}</select></label></div>`}
function enrichSummaryDrivers(summary,routes){const byBase=Object.fromEntries(aggregateRoutes(routes,state.mode).map(r=>[r.base,r]));return summary.map(row=>{const source=byBase[row.base];return source?{...row,driver_names:source.driver_names,driver_name:source.driver_name}:row})}
// Regra permanente equivalente às fórmulas da aba LOGICA!J:K.
// J/K é uma referência única; os meses seguintes precisam somente da aba DADOS.
const FF_LOGIC_RULE = Object.freeze({
  plannedDays: 26,
  countedStatuses: Object.freeze(['PLACA BIPADA','RESERVA BIPADA']),
  minDs: 92,
  utilizationBands: Object.freeze([
    Object.freeze({min: 1, payout: 1000}),
    Object.freeze({min: .95, payout: 700}),
    Object.freeze({min: .9, payout: 350})
  ])
});
function toast(message){const n=document.createElement('div');n.className='toast';n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),3200)}
function payoutProxy(r){const ds=numericValue(r.ff_ds),share=numericValue(r.ff_share);if(!Number.isFinite(share)||!Number.isFinite(ds)||ds<FF_LOGIC_RULE.minDs)return 0;return FF_LOGIC_RULE.utilizationBands.find(b=>share>=b.min)?.payout||0}
function status(r){const ds=numericValue(r.ff_ds),share=numericValue(r.ff_share);if(!r.ff)return ['Sem rotas FF elegíveis','red-b'];if(!Number.isFinite(ds))return ['Aguardando DS do Mercado Livre','yellow-b'];if(!Number.isFinite(share))return ['Aguardando LOGICA FF','yellow-b'];if(ds<FF_LOGIC_RULE.minDs)return ['DS abaixo de 92%','red-b'];if(share>=.9)return ['Faixa atingida','green-b'];return ['Faixa não atingida','red-b']}
function numericValue(value){return value===null||value===undefined||value===''?NaN:Number(value)}
function routeDsStats(routes){const total=routes.length,eligible=routes.filter(r=>{const ds=numericValue(r.ds);return Number.isFinite(ds)&&ds>=.92}).length,notEligible=routes.filter(r=>{const ds=numericValue(r.ds);return Number.isFinite(ds)&&ds<.92}).length,awaiting=total-eligible-notEligible;return {total,eligible,notEligible,awaiting}}
function card(icon,color,label,value,note){if(label==='Bônus proxy'){label='Bônus estimado';value='—';note='depende do cadastro de veículos'}return `<article class="kpi"><div class="kpi-icon ${color}">${icon}</div><div><span>${label}</span><strong>${value}</strong><small>${note}</small></div></article>`}
function header(title,subtitle,action=''){return `<div class="view-title"><div><span class="section-kicker">OPERAÇÃO · ${monthLabel(selectedDataMonth()).toUpperCase()}</span><h2>${title}</h2><p>${subtitle}</p></div>${action}</div>`}
function toolbar(placeholder){return `<div class="filterbar"><input class="search-input" id="viewSearch" placeholder="${placeholder}" value="${esc(state.query)}" /></div>`}
function chartWeek(date){const key=routeDayKey(date);if(!key)return null;const d=new Date(key+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));const months=['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];return {key:d.toISOString().slice(0,10),label:String(d.getUTCDate()).padStart(2,'0')+' '+months[d.getUTCMonth()]}}
function weeklyMetrics(){const grouped={};state.routes.forEach(r=>{if(!Number.isFinite(numericValue(r.ds)))return;const w=chartWeek(r.date);if(!w)return;const g=grouped[w.key]??={...w,ds:0,count:0};g.ds+=Number(r.ds)*100;g.count++});return Object.values(grouped).sort((a,b)=>a.key.localeCompare(b.key)).map(g=>({...g,ds:g.count?g.ds/g.count:null}))}
function trendChart(){const metrics=weeklyMetrics();if(!metrics.length)return '<text class="chart-label" x="360" y="130" text-anchor="middle">Sem dados para o período</text>';const ds=metrics.map(m=>m.ds),summary=state.ffSummary.filter(r=>Number.isFinite(Number(r.ff_share))),utilValue=state.mode==='ff'&&summary.length?summary.reduce((n,r)=>n+Number(r.ff_share)*100,0)/summary.length:null,util=utilValue===null?[]:metrics.map(()=>utilValue),all=[...ds,...util],min=Math.max(0,Math.floor(Math.min(...all)/5)*5-5),max=Math.min(110,Math.ceil(Math.max(...all)/5)*5+5),span=Math.max(1,max-min),w=720,h=260,p={l:34,r:12,t:12,b:28},x=i=>p.l+i*(w-p.l-p.r)/Math.max(1,metrics.length-1),y=v=>h-p.b-(v-min)*(h-p.t-p.b)/span;let o='';[min,(min+max)/2,max].forEach(v=>o+=`<line class="chart-grid" x1="${p.l}" x2="${w-p.r}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-label" x="0" y="${y(v)+3}">${Math.round(v)}%</text>`);metrics.forEach((m,i)=>o+=`<text class="chart-label" text-anchor="middle" x="${x(i)}" y="${h-5}">${m.label}</text>`);const path=a=>a.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ');o+=`<path class="chart-path" stroke="#7368f0" d="${path(ds)}"/>`;if(util.length)o+=`<path class="chart-path" stroke="#62a4e9" d="${path(util)}"/>`;ds.forEach((v,i)=>o+=`<circle cx="${x(i)}" cy="${y(v)}" r="3.5" fill="#fff" stroke="#7368f0" stroke-width="2"/>`);util.forEach((v,i)=>o+=`<circle cx="${x(i)}" cy="${y(v)}" r="3.5" fill="#fff" stroke="#62a4e9" stroke-width="2"/>`);return o}
function spotMonthlyBonusMap(){const dispatcher=spotDispatchers(),out={};spotMonthlyMetrics().forEach(metric=>{const band=spotBandForCars(metric.cars),bonus=band?band[dispatcher===1?'total':dispatcher===2?'two':dispatcher===3?'three':'four']:0,entry=out[metric.base]??={cars:0,bonus:0,eligibleRoutes:0};entry.cars+=metric.cars;entry.bonus+=bonus;entry.eligibleRoutes+=metric.eligibleRoutes});return out}
function rankingRows(){if(state.mode==='spot'){const bonuses=spotMonthlyBonusMap();return state.summary.map(r=>{const detail=bonuses[r.base];return detail?{...r,spot_cars:detail.cars,spot_bonus:detail.bonus,spot_eligible_routes:detail.eligibleRoutes}:null}).filter(r=>r&&r.spot_bonus>0).sort((a,b)=>b.spot_bonus-a.spot_bonus||Number(b.ff_ds||0)-Number(a.ff_ds||0))}return state.summary.filter(r=>payoutProxy(r)>0).sort((a,b)=>payoutProxy(b)-payoutProxy(a)||Number(b.ff_ds||0)-Number(a.ff_ds||0))}
function ranking(rows){rows=rankingRows();const spot=state.mode==='spot';if(!rows.length)return `<tr><td colspan="7" class="empty-state">${spot?'Nenhuma base atingiu uma faixa Spot no mês selecionado.':'Nenhuma base atingiu uma faixa de bônus FF no mês selecionado.'}</td></tr>`;return rows.map((r,i)=>{const [label,cls]=status(r),bonus=spot?Number(r.spot_bonus||0):payoutProxy(r),spotLabel='Faixa atingida',spotCars=Number(r.spot_cars||0);return `<tr><td>${String(i+1).padStart(2,'0')}</td><td><span class="base-name">${esc(r.base)}</span><span class="sub">${spot?Number(r.spot_eligible_routes||0).toLocaleString('pt-BR')+' rotas DS elegível · '+spotCars.toFixed(1).replace('.',',')+' média/dia':Number(r.total||0).toLocaleString('pt-BR')+' rotas FF'}</span></td><td class="util">${spot?Number(r.ff||0).toLocaleString('pt-BR'):(Number.isFinite(Number(r.ff_share))?pct(r.ff_share):'—')}</td><td class="ds">${pctWhole(r.ff_ds)}</td><td><b>${bonusBandLabel(r)}</b></td><td><b>${spot?moneyExact(bonus):(Number.isFinite(Number(r.ff_share))?money(bonus):'—')}</b></td><td><span class="badge ${spot?'green-b':cls}">${spot?spotLabel:label}</span></td></tr>`}).join('')}
function dashboard(){const s=state.summary,total=s.reduce((n,r)=>n+Number(r.total||0),0),ff=s.reduce((n,r)=>n+Number(r.ff||0),0),amb=s.reduce((n,r)=>n+Number(r.ambulance||0),0),ds=ff?s.reduce((n,r)=>n+Number(r.ff_ds||0)*Number(r.ff||0),0)/ff:0,off=s.filter(r=>Number.isFinite(Number(r.ff_ds))&&Number(r.ff_ds)<92&&r.ff>0).length;return `<section class="hero"><div><span class="pill purple">DADOS REAIS · ${monthLabel(selectedDataMonth()).toUpperCase()}</span><h2>Performance que vira <em>resultado.</em></h2><p>Rotas, Base, DS, ambulâncias e situação de cada base em um só lugar.</p></div><div class="hero-rule"><span>fonte processada</span><strong>Geral <small>· XLSX</small></strong><div class="progress"><i style="width:100%"></i></div><small>arquivo carregado e validado</small></div></section><section class="kpi-grid">${card('↗','green','DS médio FF',pctWhole(ds),'média ponderada nas rotas elegíveis')}${card('◎','blue','Total rotas FF',total.toLocaleString('pt-BR'),`${ff.toLocaleString('pt-BR')} rotas FF elegíveis`)}${card('$','orange','Bônus proxy','R$ 0','aguarda utilização FF oficial')}${card('!','red','Bases com DS ofensor',off,`${amb.toLocaleString('pt-BR')} ambulâncias · Cluster ROTA`)}</section><section class="content-grid"><article class="card chart-card"><div class="card-head"><div><span class="section-kicker">EVOLUÇÃO DA OPERAÇÃO</span><h3>DS% e utilização por semana</h3></div><div class="legend"><span><i class="legend-line purple-line"></i>DS% rota</span><span><i class="legend-line blue-line"></i>Utilização FF</span></div></div><div class="chart-wrap"><svg viewBox="0 0 720 260">${trendChart()}</svg></div><div class="chart-note"><span class="note-icon">↗</span><span><b>Fonte:</b> dados oficiais importados do Mercado Livre, DDS e LOGICA FF. O gráfico e os indicadores são recalculados a cada atualização.</span></div></article><article class="card rule-card"><div class="card-head"><div><span class="section-kicker">REGRA VIGENTE</span><h3>Faixas de bônus FF</h3></div><button class="text-button" data-action="rules">Ver regras →</button></div><p class="rule-intro">O DS por rota precisa atingir <b>92%</b>. Depois, a utilização média mensal define a faixa.</p><div class="rule-list"><div class="rule-row"><span class="rule-check">✓</span><strong>100%</strong><span>utilização FF</span><b class="money">R$ 1.000</b></div><div class="rule-row"><span class="rule-check">✓</span><strong>95%</strong><span>utilização FF</span><b class="money">R$ 700</b></div><div class="rule-row"><span class="rule-check">✓</span><strong>90%</strong><span>utilização FF</span><b class="money">R$ 350</b></div></div><div class="rule-foot"><span>Ambulância: Cluster = ROTA</span><strong>Reserva: cadastro</strong></div></article></section><section class="lower-grid"><article class="card ranking-card"><div class="card-head"><div><span class="section-kicker">RANKING DE BASES</span><h3>As bases que estão fazendo acontecer</h3></div><button class="secondary-button" data-action="bases">Ver todas as bases</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>#</th><th>BASE</th><th>PARTICIPAÇÃO FF*</th><th>DS MÉDIO</th><th>AMB.</th><th>BÔNUS*</th><th>STATUS</th></tr></thead><tbody>${ranking(s.slice(0,10))}</tbody></table></div></article><article class="card impact-card"><div class="card-head"><div><span class="section-kicker">FONTE PRINCIPAL</span><h3>Base operacional</h3></div></div><div class="impact-big"><strong>COLUNA A</strong><span>Base da aba Geral</span></div><div class="callout">O painel usa a primeira coluna do arquivo como identificador da Base e agrupa as rotas por esse campo.</div><div class="impact-footer"><span class="mini-avatar">+</span><span>Dados atualizados<br /><b>recalculados após cada importação</b></span></div></article></section>`}
function buildPlateRanking(rows){const grouped={};rows.filter(r=>!r.isAmb&&String(r.cluster||'').toUpperCase()!=='ROTA').forEach(r=>{const plate=String(r.placa||'').trim();if(!plate)return;const g=grouped[plate]??={placa:plate,rotas:0,ds:0,reservas:0,bases:{},driverCounts:{}};g.rotas++;g.ds+=Number(r.ds||0);g.bases[r.base]=(g.bases[r.base]||0)+1;const driver=String(r.motorista||'').trim();if(driver)g.driverCounts[driver]=(g.driverCounts[driver]||0)+1;if(r.source_type==='RESERVA FF')g.reservas++});return Object.values(grouped).map(r=>{const driver_names=Object.entries(r.driverCounts).sort((a,b)=>b[1]-a[1]).map(([name])=>name);return {...r,driver_names,ds:r.rotas?r.ds/r.rotas:null,base:Object.entries(r.bases).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—'}}).filter(r=>Number.isFinite(r.ds)&&r.ds>=.92).sort((a,b)=>b.ds-a.ds||b.rotas-a.rotas).slice(0,6)}
function plateRanking(){return (state.plateRankings[state.mode]||[]).map((r,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td><b>${esc(r.placa)}</b>${r.reservas?`<span class="sub">${r.reservas} Reserva FF</span>`:''}</td><td>${esc(driverLabel(r))}</td><td>${esc(r.base)}</td><td>${r.rotas.toLocaleString('pt-BR')}</td><td class="ds"><b>${pct(r.ds)}</b></td><td><span class="badge green-b">Melhor DS</span></td></tr>`).join('')}
