async function hydrateLatestImports(){try{const statusResponse=await fetch('/api/imports/status',{cache:'no-store'});if(!statusResponse.ok)return false;const statusSources=(await statusResponse.json()).sources||{},signature=Object.entries(statusSources).sort(([a],[b])=>a.localeCompare(b)).map(([key,value])=>key+':'+(value.importedAt||value.fileName||'')+':'+(value.rowCount||0)).join('|');if(signature&&signature===latestImportsSignature)return false;const response=await fetch('/api/imports/latest',{cache:'no-store'});if(!response.ok)return false;const sources=(await response.json()).sources||{};if(signature)latestImportsSignature=signature;const dds=sources.DDS?.rows,mercado=sources.MERCADO_LIVRE?.rows,logic=sources.LOGICA_FF?.rows,fleet=sources.FF_LOCADORA?.rows;if(Array.isArray(dds)){state.ddsRows=dds;state.ddsRoutes=ddsRoutesFromRows(dds)}if(Array.isArray(mercado))state.mercadoRows=mercado;if(Array.isArray(logic)){state.ffLogicRows=mergeLogicRows(readLogicRows(logic));refreshLogicSummary()}if(Array.isArray(fleet))setFleetReference({master:fleet.map(raw=>{const r=normalized(raw);return {plate:r.plate||r.placa||'',type:fleetType(r.type||r.ffoulocadora)}})});if(Array.isArray(dds)||Array.isArray(mercado)||Array.isArray(logic)||Array.isArray(fleet)){applyLogicToRoutes();if(state.mercadoRows.length)applyMercadoToRoutes();return true}}catch(error){console.warn('Importações salvas não carregadas',error)}return false}
async function readImportSheet(file,matcher){if(!file.name.toLowerCase().endsWith('.xlsx'))return parseCsv(await file.text());if(!window.XLSX)throw new Error('Leitor XLSX indisponível');const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});const name=book.SheetNames.find(n=>matcher(String(n).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()))||book.SheetNames[0];return XLSX.utils.sheet_to_json(book.Sheets[name],{defval:''})}
async function readFleetReference(file){if(!file.name.toLowerCase().endsWith('.xlsx')){const rows=parseCsv(await file.text());return {master:rows.map(raw=>{const r=normalized(raw);return {plate:r.placa||'',type:fleetType(r.tipo||r.modalidade||r.ffoulocadora)}}).filter(r=>r.plate&&r.type)}}if(!window.XLSX)throw new Error('Leitor XLSX indisponível');const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),sheetName=book.SheetNames.find(n=>String(n).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes('ff ou locadora'))||book.SheetNames[0],masterRows=XLSX.utils.sheet_to_json(book.Sheets[sheetName],{defval:''});return {master:masterRows.map(raw=>{const r=normalized(raw);return {plate:r.placa||'',type:fleetType(r.ffoulocadora||r.tipo||r.modalidade)}}).filter(r=>r.plate&&r.type)}}
async function handleDdsImport(e){const file=e.target.files[0];if(!file)return;try{const rows=await readImportSheet(file,n=>n.includes('geral'));state.ddsRows=rows;state.ddsRoutes=ddsRoutesFromRows(rows);const stored=await persistImport(file,'DDS',rows);applyLogicToRoutes();applyMercadoToRoutes();render();toast(rows.length.toLocaleString('pt-BR')+' linhas DDS carregadas · '+stored.recordsUpserted.toLocaleString('pt-BR')+' salvas no banco.')}catch(error){console.error(error);toast('Não foi possível ler a planilha DDS.')}}
