function importView(){return header('Importar dados','Atualize o painel com as fontes oficiais da operação.')+'<article class="card dropzone"><strong>1. Importar DDS completo</strong><p>Arquivo com todas as rotas. A aba Geral será usada para Base, placa e rota.</p><label class="upload-button">＋ Selecionar DDS<input type="file" id="ddsInput" accept=".xlsx,.csv" /></label></article><article class="card dropzone" style="margin-top:14px"><strong>2. Importar Mercado Livre</strong><p>Somente a aba de entregas com sucesso será usada para atualizar o DS das rotas.</p><label class="upload-button">＋ Selecionar Mercado Livre<input type="file" id="mercadoInput" accept=".xlsx,.csv" /></label></article><article class="card dropzone" style="margin-top:14px"><strong>3. Importar LOGICA FF</strong><p>A aba DADOS define placas, Base, data, status de bipagem e reservas. A regra fixa da aba LOGICA/J:K já está gravada: ${FF_LOGIC_RULE.countedStatuses.join(' + ')} ÷ (${FF_LOGIC_RULE.plannedDays} dias planejados × placas únicas da base). Nos próximos meses, envie somente a aba DADOS; J/K não precisa ser reenviada.</p><label class="upload-button">＋ Selecionar LOGICA FF<input type="file" id="logicInput" accept=".xlsx,.csv" /></label><div class="status-row" style="justify-content:center;margin-top:12px">'+state.ffLogicRows.length.toLocaleString('pt-BR')+' registros de lógica FF carregados.</div></article><article class="card dropzone" style="margin-top:14px"><strong>4. Importar FF OU LOCADORA</strong><p>As placas classificadas como FF ou Locadora na aba FF OU LOCADORA são retiradas do cálculo Spot. A aba Base e a PLACA2 não participam deste cruzamento.</p><label class="upload-button">＋ Selecionar FF OU LOCADORA<input type="file" id="fleetReferenceInput" accept=".xlsx,.csv" /></label><div class="status-row" style="justify-content:center;margin-top:12px">'+state.fleetReference.master.length.toLocaleString('pt-BR')+' placas classificadas.</div></article>'}
function bindEvents(){document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.action;if(a==='rules')setView('regras');if(a==='bases')setView('bases');if(a==='rotas')setView('rotas');if(a==='import')setView('importar');if(a==='routePrev'){state.routePage--;render()}if(a==='routeNext'){state.routePage++;render()}if(a==='downloadRoutes')downloadRoutes();if(a==='downloadTemplate')downloadTemplate()}));document.querySelectorAll('.mode-button').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));const month=document.querySelector('#monthSelect');if(month)month.addEventListener('change',()=>{refreshLogicSummary();refreshSummaries();render()});const search=document.querySelector('#viewSearch');if(search)search.addEventListener('input',e=>{state.query=e.target.value;state.routePage=1;const pos=search.selectionStart;render();const next=document.querySelector('#viewSearch');next.focus();next.setSelectionRange(pos,pos)});const dds=document.querySelector('#ddsInput');if(dds)dds.addEventListener('change',handleDdsImport);const ml=document.querySelector('#mercadoInput');if(ml)ml.addEventListener('change',handleMercadoImport);const logic=document.querySelector('#logicInput');if(logic)logic.addEventListener('change',handleLogicImport);const fleetReference=document.querySelector('#fleetReferenceInput');if(fleetReference)fleetReference.addEventListener('change',handleFleetReferenceImport);const dispatcher=document.querySelector('#spotDispatcherCount');if(dispatcher)dispatcher.addEventListener('change',e=>{localStorage.setItem('spotDispatchers',e.target.value);render()})}
const bindEventsWithBaseSorting=bindEvents;
bindEvents=()=>{bindEventsWithBaseSorting();const sort=document.querySelector('#baseSortSelect');if(sort)sort.addEventListener('change',e=>{state.baseSort=e.target.value;state.routePage=1;render()});document.querySelectorAll('[data-action="bases"]').forEach(button=>button.addEventListener('click',()=>{state.baseSort=button.dataset.sort||'ranking';setView('bases')}))};
function modeName(){return state.mode==='spot'?'Spot':'Frota Fixa'}
function modeContent(content){if(state.mode!=='spot')return content;return content.replaceAll('Frota Fixa','Spot').replaceAll('rotas FF','rotas Spot').replaceAll('Rotas FF','Rotas Spot').replaceAll('DS médio FF','DS médio Spot').replaceAll('PARTICIPAÇÃO FF','ROTAS SPOT').replaceAll('BÔNUS*','BÔNUS SPOT').replaceAll('bônus FF','bônus Spot').replaceAll('utilização FF','utilização Spot').replaceAll('Utilização FF','Utilização Spot').replaceAll('Reserva: PLACA2','Modalidade: Spot').replaceAll('Reserva FF','Spot').replaceAll('Reserva de Spot','Reserva de Frota Fixa')}
const spotBandsConfig=[{cars:10,total:1000,two:500,three:333.33,four:250},{cars:15,total:1500,two:750,three:500,four:375},{cars:25,total:2000,two:1000,three:666.67,four:500},{cars:35,total:3000,two:1500,three:1000,four:750},{cars:45,total:4000,two:2000,three:1333.33,four:1000},{cars:55,total:5000,two:2500,three:1666.67,four:1250},{cars:65,total:6000,two:3000,three:2000,four:1500},{cars:75,total:7000,two:3500,three:2333.33,four:1750},{cars:85,total:8000,two:4000,three:2666.67,four:2000},{cars:95,total:9000,two:4500,three:3000,four:2250},{cars:105,total:10000,two:5000,three:3333.33,four:2500}];
const moneyExact=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:0,maximumFractionDigits:0});
function spotDispatchers(){const n=Number(localStorage.getItem('spotDispatchers')||1);return [1,2,3,4].includes(n)?n:1}
function spotBands(){return `<div class="spot-table-wrap"><table class="spot-rule-table"><thead><tr><th>FAIXA SPOT MÉDIA/DIA</th><th>VALOR</th><th>2 DISPATCHER</th><th>3 DISPATCHER</th><th>4 DISPATCHER</th></tr></thead><tbody>${spotBandsConfig.map(b=>`<tr><td>${b.cars} carros</td><td>${moneyExact(b.total)}</td><td>${moneyExact(b.two)}</td><td>${moneyExact(b.three)}</td><td>${moneyExact(b.four)}</td></tr>`).join('')}</tbody></table></div>`}
function spotMonthlyMetrics(){const month=selectedDataMonth();if(spotMetricsCache.routes===state.spotRoutes&&spotMetricsCache.month===month&&spotMetricsCache.metrics)return spotMetricsCache.metrics;const months={};state.spotRoutes.filter(r=>routeMonth(r.date)===month).forEach(r=>{if(Number(r.ds||0)<.92)return;const base=String(r.base||'Base sem nome').trim(),key=base+'|'+month,g=months[key]??={base,month,eligibleRoutes:0};g.eligibleRoutes++});spotMetricsCache={routes:state.spotRoutes,month,metrics:Object.values(months).map(g=>{const [year,month]=g.month.split('-').map(Number),days=year&&month?new Date(Date.UTC(year,month,0)).getUTCDate():0;return {...g,daysInMonth:days,cars:days?g.eligibleRoutes/days:0}})};return spotMetricsCache.metrics}
function spotBandForCars(cars){return [...spotBandsConfig].reverse().find(b=>cars>=b.cars)||null}
function spotProjectedBonus(){const dispatcher=spotDispatchers();return spotMonthlyMetrics().reduce((sum,d)=>{const b=spotBandForCars(d.cars);return sum+(b?b[dispatcher===1?'total':dispatcher===2?'two':dispatcher===3?'three':'four']:0)},0)}
function spotBonusKpi(){const bases=spotMonthlyMetrics().filter(d=>spotBandForCars(d.cars)).length;return `<article class="kpi"><div class="kpi-icon orange">$</div><div><span>Bônus Spot projetado no mês</span><strong>${moneyExact(spotProjectedBonus())}</strong><small>Soma de ${bases} bases/mês · ${spotDispatchers()} dispatcher(es)</small></div></article>`}
function spotRuleCard(){return `<article class="card rule-card"><div class="card-head"><div><span class="section-kicker">REGRA SPOT</span><h3>Faixa Spot pela média diária</h3></div><button class="text-button" data-action="rules">Ver regras →</button></div><div class="spot-dispatcher-control"><label for="spotDispatcherCount">Quantidade de dispatchers</label><select id="spotDispatcherCount"><option value="1" ${spotDispatchers()===1?'selected':''}>1 dispatcher</option><option value="2" ${spotDispatchers()===2?'selected':''}>2 dispatchers</option><option value="3" ${spotDispatchers()===3?'selected':''}>3 dispatchers</option><option value="4" ${spotDispatchers()===4?'selected':''}>4 dispatchers</option></select></div>${spotBands()}</article>`}
function spotRulesPage(){return `${header('Regras Spot','Parâmetros específicos da modalidade Spot.')}<section class="content-grid"><article class="card"><div class="card-head"><div><span class="section-kicker">REGRA SPOT</span><h3>Portão de DS</h3></div></div><p class="rule-intro">Cada rota Spot precisa atingir <b>92%</b> de DS. A faixa usa as rotas elegíveis divididas pela quantidade de dias do mês.</p></article><article class="card"><div class="card-head"><div><span class="section-kicker">FAIXA SPOT</span><h3>Valores pela média diária</h3></div></div><div class="spot-dispatcher-control"><label for="spotDispatcherCount">Quantidade de dispatchers</label><select id="spotDispatcherCount"><option value="1" ${spotDispatchers()===1?'selected':''}>1 dispatcher</option><option value="2" ${spotDispatchers()===2?'selected':''}>2 dispatchers</option><option value="3" ${spotDispatchers()===3?'selected':''}>3 dispatchers</option><option value="4" ${spotDispatchers()===4?'selected':''}>4 dispatchers</option></select></div>${spotBands()}</article></section>`}
function dashboard(){const content=dashboardFFView();if(state.mode!=='spot')return content;return modeContent(content).replace(/<article class="kpi"><div class="kpi-icon orange">[\s\S]*?<\/article>/,spotBonusKpi()).replace(/<article class="card rule-card">[\s\S]*?<\/article>/,spotRuleCard()).replace('<span><i class="legend-line blue-line"></i>Utilização Spot</span>','').replace(/<path class="chart-path" stroke="#62a4e9"[^>]*\/>/,'').replace(/<circle[^>]*stroke="#62a4e9"[^>]*\/>/g,'').replace('<b>Fonte:</b> DS vem da coluna AB. A Base vem da coluna A. A utilização oficial depende da frota planejada e Reserva FF.','<b>Fonte:</b> DS vem da coluna AB. A Base vem da coluna A.');}
function rulesView(){if(state.mode==='spot')return spotRulesPage();return rulesFFView().replace('</section>','<article class="card weekly-rest-rule"><div class="card-head"><div><span class="section-kicker">FONTE DA UTILIZAÇÃO</span><h3>LOGICA FF · aba DADOS</h3></div></div><p class="rule-intro">A utilização oficial vem da planilha LOGICA FF: bipagens <b>PLACA BIPADA</b> + <b>RESERVA BIPADA</b>, divididas por <b>${FF_LOGIC_RULE.plannedDays} dias planejados × placas únicas da base</b>. A aba LOGICA é usada para validar essa mesma regra; não precisa ser reenviada nos próximos meses.</p></article></section>')}
function render(){const month=selectedDataMonth(),periodRoutes=(state.mode==='spot'?state.spotRoutes:state.ffRoutes).filter(r=>routeMonth(r.date)===month);state.routes=periodRoutes;state.summary=enrichSummaryDrivers(state.summary,periodRoutes);if(state.mode==='ff')state.ffSummary=state.summary;else state.spotSummary=state.summary;document.querySelector('#routeNavCount')?.replaceChildren(document.createTextNode(periodRoutes.length.toLocaleString('pt-BR')));document.querySelector('#baseNavCount')?.replaceChildren(document.createTextNode(String(state.summary.length)));const content=state.view==='dashboard'?dashboard():state.view==='rotas'?routesView():state.view==='bases'?basesView():state.view==='regras'?rulesView():importView();app.innerHTML=modeContent(content);document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.view===state.view));document.querySelector('#pageTitle').innerHTML=({dashboard:`${modeName()} <span>/</span> visão mensal`,rotas:`${modeName()} <span>/</span> rotas`,bases:`${modeName()} <span>/</span> bases`,regras:`${modeName()} <span>/</span> regras`,importar:`${modeName()} <span>/</span> dados`}[state.view]);document.querySelectorAll('.mode-button').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));bindEvents()}
function saveSpotValues(){const values={};document.querySelectorAll('.spot-value').forEach(input=>{values[input.dataset.spotValue]=input.value.trim()});localStorage.setItem('spotPayouts',JSON.stringify(values));toast('Valores das faixas Spot salvos.');}
function setMode(mode){const next=mode==='spot'?'spot':'ff';if(next===state.mode)return;state.mode=next;state.summary=state.mode==='spot'?state.spotSummary:state.ffSummary;state.routes=state.mode==='spot'?state.spotRoutes:state.ffRoutes;state.query='';state.routePage=1;document.querySelector('#routeNavCount')?.replaceChildren(document.createTextNode(state.routes.length.toLocaleString('pt-BR')));document.querySelector('#baseNavCount')?.replaceChildren(document.createTextNode(String(state.summary.length)));cancelAnimationFrame(modeSwitchFrame);modeSwitchFrame=requestAnimationFrame(()=>{render();requestAnimationFrame(()=>document.body.classList.remove('mode-switching'))});document.body.classList.add('mode-switching')}
function setView(view){state.view=view;state.query='';state.routePage=1;location.hash=view;render()}
function download(name,content){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));link.download=name;link.click();URL.revokeObjectURL(link.href)}
function downloadRoutes(){const body=state.routes.map(r=>[r.date,r.base,r.motorista,r.placa,r.rota,r.cluster,r.ds*100].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');download(`rotas_${state.mode}_${selectedDataMonth()||'periodo'}.csv`,'data,base,motorista,placa,rota,cluster,ds_pct\n'+body);toast('CSV de rotas exportado.')}
function parseCsv(text){const lines=text.trim().split(/\r?\n/).filter(Boolean),split=line=>line.match(/("(?:[^"]|"")*"|[^,]+)/g)?.map(v=>v.replace(/^"|"$/g,'').replaceAll('""','"').trim())||[],headers=split(lines.shift()).map(v=>v.toLowerCase());return lines.map(line=>Object.fromEntries(headers.map((h,i)=>[h,split(line)[i]||''])))}
function normalized(row){const out={};Object.entries(row).forEach(([key,value])=>{const k=String(key).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');out[k]=value});return out}
function slashDateKey(s,defaultOrder='dmy'){const m=s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})(?:\D|$)/);if(!m)return '';const a=Number(m[1]),b=Number(m[2]),day=a>12?a:b>12?b:defaultOrder==='mdy'?b:a,month=a>12?b:b>12?a:defaultOrder==='mdy'?a:b;return `${m[3]}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function routeDayKey(value){const s=String(value??'').trim(),slash=slashDateKey(s,'dmy');if(slash)return slash;const d=new Date(s);return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,10)}
function ddsDateKey(value){if(value instanceof Date)return String(value.getFullYear())+'-'+String(value.getMonth()+1).padStart(2,'0')+'-'+String(value.getDate()).padStart(2,'0');const s=String(value??'').trim();return slashDateKey(s,'mdy')||routeDayKey(s)}
function routeMonth(value){return (routeDayKey(value)||'').slice(0,7)}

function plateNorm(v){return String(v??'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]/g,'')}
function driverNorm(v){return String(v??'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]+/g,' ').trim().replace(/\s+/g,' ')}
async function persistImport(file,sourceType,rows){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));const response=await fetch('/api/imports',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sourceType,fileName:file.name,mimeType:file.type||'application/octet-stream',fileBase64:btoa(binary),rows})});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).error||'Falha ao salvar no banco');return response.json()}
function excelDateLabel(value){const n=Number(value);if(!Number.isFinite(n))return String(value??'');const d=new Date(Date.UTC(1899,11,30)+n*86400000);return String(d.getUTCDate()).padStart(2,'0')+'/'+String(d.getUTCMonth()+1).padStart(2,'0')+'/'+d.getUTCFullYear()}
async function load(){try{const [summary,routes,spotSummary,spotRoutes,logicRows,logicSummary,fleetReference]=await Promise.all([fetch('outputs/thread-01/ff_summary.json').then(r=>r.json()),fetch('outputs/thread-01/ff_routes.json').then(r=>r.json()),fetch('outputs/thread-01/spot_summary.json').then(r=>r.json()),fetch('outputs/thread-01/spot_routes.json').then(r=>r.json()),fetch('outputs/thread-01/ff_logic_rows.json').then(r=>r.json()),fetch('outputs/thread-01/ff_logic_summary.json').then(r=>r.json()),fetch('outputs/thread-01/fleet_reference.json').then(r=>r.json())]);const mapSummary=rows=>rows.map(r=>({...r,project:r.project||''}));const mapRoutes=rows=>rows.map(r=>({base:r.base,project:r.project||'',date:r.data_serial?excelDateLabel(r.data_serial):'',placa:r.placa,motorista:String(r.motorista||r.nomemotorista||r.nomedomotorista||r.nomecondutor||r.driver||r.drivername||'').trim(),rota:r.rota,cluster:r.cluster,ds:Number(r.ds||0)/100,ds_source:'LEGACY_SNAPSHOT',source_type:r.source_type||'RENTALS'}));state.ffSummary=mapSummary(summary);state.ffRoutes=mapRoutes(routes);state.spotSummary=mapSummary(spotSummary);state.spotRoutes=mapRoutes(spotRoutes);state.snapshotFFRoutes=state.ffRoutes.map(r=>({...r}));state.snapshotSpotRoutes=state.spotRoutes.map(r=>({...r}));state.snapshotFFSummary=state.ffSummary.map(r=>({...r}));state.plateRankings={ff:buildPlateRanking(state.ffRoutes),spot:buildPlateRanking(state.spotRoutes)};state.summary=state.ffSummary;state.routes=state.ffRoutes;state.ffLogicRows=readLogicRows(logicRows);state.ffLogicSummary=logicSummary;setFleetReference(fleetReference);applyLogicToRoutes();await hydrateLatestImports();document.querySelector('#routeNavCount').textContent=state.routes.length.toLocaleString('pt-BR');document.querySelector('#baseNavCount').textContent=state.summary.length;render();window.setInterval(async()=>{if(await hydrateLatestImports())render()},60000)}catch(error){console.error(error);app.innerHTML='<div class="card empty-state">Não foi possível carregar os dados locais de julho. Verifique se o servidor está aberto na pasta do projeto.</div>'}}
document.querySelectorAll('.nav-link').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();setView(a.dataset.view)}));document.querySelector('#globalSearchButton').addEventListener('click',()=>{const search=document.querySelector('#viewSearch');if(search)search.focus();else{setView('bases');setTimeout(()=>document.querySelector('#viewSearch')?.focus(),0)}});window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['dashboard','rotas','bases','regras','importar'].includes(view)){state.view=view;render()}});load();
